mapper.select:
SELECT id, invitation_code AS invitationCode, name, phone, company, position, reason, status, review_remark AS reviewRemark, created_at AS createdAt, reviewed_at AS reviewedAt FROM t_application
status = #{status}
ORDER BY id DESC

mapper.update:
UPDATE t_application
SET status = #{status}, review_remark = #{reviewRemark}, reviewed_at = NOW()
WHERE id = #{id}
